mapper.select:
SELECT mqcc.*, mbp.id AS 'process.id', mbp.name AS 'process.name' FROM mes_quota_config_coating mqcc LEFT JOIN mes_building_process mbp ON mbp.bool_delete_enum = 0 AND mbp.id = mqcc.process_id WHERE mqcc.bool_delete_enum = 0
AND FIND_IN_SET(#{branchCompanyId}, mqcc.branch_company_ids) > 0
AND FIND_IN_SET(#{workshopId}, mqcc.workshop_ids) > 0
AND FIND_IN_SET(#{productClassId}, mqcc.artifact_class_ids) > 0
AND mqcc.process_id = #{processId}
AND (
FIND_IN_SET(#{bcId}, mqcc.branch_company_ids) > 0
)
AND (
FIND_IN_SET(#{wId}, mqcc.workshop_ids) > 0
)
AND (
FIND_IN_SET(#{pcId}, mqcc.artifact_class_ids) > 0
)
AND (
mqcc.process_id = #{pId}
)
